import math


def rebalance_table(table, shrink):
    if not isinstance(table, list):
        raise TypeError("table must be a list")
    if isinstance(shrink, bool) or not isinstance(shrink, (int, float)):
        raise TypeError("shrink must be a number")
    if not math.isfinite(shrink) or shrink <= 0:
        raise ValueError("shrink must be positive and finite")
    if not table:
        return []

    width = None
    for row in table:
        if not isinstance(row, list):
            raise TypeError("each row must be a list")
        if not row:
            raise ValueError("rows cannot be empty")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError("rows must have equal length")
        for value in row:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("values must be numbers")
            if not math.isfinite(value):
                raise ValueError("values must be finite")

    means = [
        sum(row[column] for row in table) / width
        for column in range(width)
    ]
    scales = [1.0 / (1.0 + abs(mean) / shrink) for mean in means]
    return [
        [value * scales[column] for column, value in enumerate(row)]
        for row in table
    ]

